import type {CommentInfo} from '../../../../../types'
import {parseDateToObj} from '../../../../../utils/dateTimeUtils'

export function getDetails(pauseComment: CommentInfo | undefined, isAutodetectTimeZone: boolean) {
  const name = pauseComment?.user?.name || pauseComment?.user?.username
  const timestamp =
    pauseComment?.timestamp != null
      ? parseDateToObj(pauseComment.timestamp, isAutodetectTimeZone).format('D MMM YY LT')
      : null
  const user = pauseComment?.user
  const text = pauseComment?.text
  const when = timestamp != null ? ` at ${timestamp}` : ''
  const details = `${name ?? ''}${when}`
  return {
    user,
    details,
    comment: text,
  }
}
