import type {BuildTypePageQuery} from './__generated__/BuildTypePageQuery.graphql'
import BuildTypeChainsTab from './BuildTypeChainsTab/BuildTypeChainsTab'
import type {BuildTypeChangeLogTabEntryPoint} from './BuildTypeChangeLogTab/BuildTypeChangeLogTab.entryPoint'
import type {BuildTypeHistoryQuery} from './BuildTypeOverviewTab/BuildTypeHistory/__generated__/BuildTypeHistoryQuery.graphql'
import BuildTypeOverviewTab from './BuildTypeOverviewTab/BuildTypeOverviewTab'
import {useRefetchBuildTypeOnPermissionsChange} from './BuildTypePage.hooks'
