import type {PendingChangesTabEntryPoint} from './PendingChangesTab/PendingChangesTab.entryPoint'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

export type NestedEntryPoints = {
  tagsFilters?: typeof TagsFiltersEntryPoint
  changeLogTab?: typeof BuildTypeChangeLogTabEntryPoint
  pendingChangesTab?: typeof PendingChangesTabEntryPoint
}

type Props = {
  buildTypeId: BuildTypeId
  buildTypeHistoryQuery?: PreloadedQuery<BuildTypeHistoryQuery>
  permalinksQuery?: PreloadedQuery<PermalinksQuery>
  branchesQueryRef: PreloadedQuery<BranchSelectBranchesQuery>
  withBranchesQueryRef: PreloadedQuery<branchExistsInBuildTypeQuery>
  entryPoints: PreloadedEntryPoints<NestedEntryPoints>
}
export function BuildTypePage({
  buildTypeId,
  buildTypeHistoryQuery,
  permalinksQuery,
  branchesQueryRef,
  withBranchesQueryRef,
  entryPoints,
}: Props) {
  const branch = useBranch()
  const location = useLocation()
  const navigate = useNavigate()
  const projectId = useAppSelector(state => getBuildType(state, buildTypeId)?.projectId)
  restApi.endpoints.getProjectNormalized.useQuerySubscription(
    projectId ? getSingleProjectArg(projectId, {withAncestorProjects: true}) : skipToken,
  )
  const arg = getBuildTypeArg(buildTypeId)
  const {rawError, actualId, refetch} = restApi.endpoints.getBuildTypeNormalized.useQuery(arg, {
    selectFromResult: ({error, data}) => ({rawError: error, actualId: data?.result}),
  })
  const internalId = useAppSelector(state => getBuildType(state, buildTypeId)?.internalId)
  useEffect(
    () =>
      internalId != null
        ? subscribeOnBuildTypeEvents(internalId, [BUILD_TYPE_UPDATED], refetch)
        : undefined,
    [internalId, refetch],
  )

  const error = extractError(rawError)
  const idChanged = actualId != null && actualId !== buildTypeId
  const withBranches = usePreloadedQuery(
    branchExistsInBuildTypeQueryDefinition,
    withBranchesQueryRef,
  ).branchExistsInBuildType
  const projectLoaded = useAppSelector(state => Boolean(getProject(state, projectId)))
  const buildTypeLoaded = useAppSelector(state => isBuildTypeLoaded(state, buildTypeId))
  const currentTabId = useQueryParam('buildTypeTab')
  const currentTab = useAppSelector(state =>
    calcNextTab(state, {tab: currentTabId, buildTypeId, branch}),
  )
  const {
    tabs: {classicTabs, sakuraTabs},
    allTabsReady,
    refetchTabs,
  } = useTabs({buildTypeId, projectId, branch})
  useEffect(
    () =>
      internalId != null
        ? subscribeOnBuildTypeEvents(
            internalId,
            [BUILD_CHANGES_LOADED, CHANGE_ADDED, BUILD_INTERRUPTED],
            refetchTabs,
          )
        : undefined,
    [internalId, refetchTabs],
  )
  const dispatch = useAppDispatch()
  useEffect(
    () =>
      internalId != null
        ? dispatch(subscribeOnBuildTypeStatus(buildTypeId, internalId, branch, 0))
        : undefined,
    [branch, buildTypeId, dispatch, internalId],
  )

  const onSelect = useCallback(
    (tab: TabId) => {
      navigate(
        getHrefWithQueryParams(location, null, params => ({
          buildTypeTab: tab,
          branch: params.branch,
        })),
        {preventScrollReset: true},
      )
    },
    [location, navigate],
  )

  const getImplementedInSakuraUITabs = useCallback(
    (id: TabId) => {
      switch (id) {
        case BuildTypePageTabNamesEnum.OVERVIEW:
          return (
            <BuildTypeOverviewTab
              branch={branch}
              buildTypeId={buildTypeId}
              withBranches={withBranches}
              buildTypeHistoryQuery={buildTypeHistoryQuery}
              permalinksQuery={permalinksQuery}
              withBranchesQueryRef={withBranchesQueryRef}
              tagsFiltersEntryPoint={entryPoints.tagsFilters}
            />
          )

        case BuildTypePageTabNamesEnum.PENDING_CHANGES:
          return (
            entryPoints.pendingChangesTab != null && (
              <EntryPointContainer
                entryPointReference={entryPoints.pendingChangesTab}
                props={{buildTypeId}}
              />
            )
          )

        case BuildTypePageTabNamesEnum.CHAINS:
          return <BuildTypeChainsTab />

        case BuildTypePageTabNamesEnum.CHANGE_LOG:
          return (
            entryPoints.changeLogTab != null && (
              <EntryPointContainer
                entryPointReference={entryPoints.changeLogTab}
                props={{buildTypeId}}
              />
            )
          )

        default:
          return null
      }
    },
    [
      branch,
      buildTypeId,
      withBranches,
      buildTypeHistoryQuery,
      permalinksQuery,
      withBranchesQueryRef,
      entryPoints,
    ],
  )

  const getTabContent = useCallback(
    ({
      tab,
      tabId,
      titleText,
      title,
    }: {
      tab?: Tab
      tabId: string
      titleText: string
      title: (arg0: boolean) => React.ReactElement
    }) => {
      const tabContent = getImplementedInSakuraUITabs(tabId)
      const Wrapper = tab?.sakura === true ? TabPlugin : ClassicUITabAdapter

      return (
        <OverviewTab
          key={stringifyId(tabId)}
          id={tabId}
          title={title}
          titleProps={{'aria-label': titleText}}
          isClassic={tabContent == null}
          href={getTabUrl({buildTypeId}, tabId)}
        >
          <Suspense fallback={<Loader />}>
            {tabContent || (
              <Wrapper
                key={stringifyBranch(branch)}
                tabId={tabId}
                title={titleText}
                projectId={projectId}
                buildTypeId={buildTypeId}
                branch={branch}
                js={tab?.js}
                css={tab?.css}
                url={tab?.url}
              />
            )}
          </Suspense>
        </OverviewTab>
      )
    },
    [branch, buildTypeId, getImplementedInSakuraUITabs, projectId],
  )

  const renderTab = useCallback(
    (tab?: Tab) => {
      let tabId = currentTab
      let titleText =
        BuildTypePageTabTitlesEnum[tabId] ??
        stringifyId(tabId).charAt(0).toUpperCase() + stringifyId(tabId).slice(1)
      let title = renderTitle(titleText)

      if (tab != null) {
        const {name, counter} = parseTabTitle(tab.title)
        tabId = tab.id
        titleText = BuildTypePageTabTitlesEnum[tabId] ?? name
        title = renderTitle(titleText, counter)
      }

      return getTabContent({title, tab, tabId, titleText})
    },
    [currentTab, getTabContent],
  )

  const classicUITabs = useMemo(
    () => (classicTabs.length ? classicTabs.map(renderTab) : emptyArray),
    [renderTab, classicTabs],
  )
  const sakuraUITabs = useMemo(
    () => (sakuraTabs.length ? sakuraTabs.map(renderTab) : [renderTab()]),
    [sakuraTabs, renderTab],
  )

  if (idChanged) {
    return <EntityRedirect buildTypeId={actualId} redirectedFromId={buildTypeId} />
  }

  if (!window.GLOBAL_ERROR_PAGE_DISABLED && error != null) {
    throw error
  }

  if (!buildTypeLoaded || !projectLoaded) {
    return <Loader />
  }

  return (
    <EntityProvider buildTypeId={buildTypeId}>
      <BuildTypePageHeader
        projectId={projectId}
        buildTypeId={buildTypeId}
        branchesQueryRef={branchesQueryRef}
      />
      <Tabs
        className={tabStyles.tabs}
        data-test="overview-tabs-panel"
        selected={currentTab}
        onSelect={onSelect}
        autoCollapse={process.env.NODE_ENV !== 'test'}
        initialVisibleItems={3}
      >
        {sakuraUITabs}
        {classicUITabs}
        {!allTabsReady && (
          <CustomItem key="tabs_loader">
            <TabsLoader />
          </CustomItem>
        )}
      </Tabs>
    </EntityProvider>
  )
}

export type Queries = {
  main: BuildTypePageQuery
  buildTypeHistory?: BuildTypeHistoryQuery
  permalinks?: PermalinksQuery
  branches: BranchSelectBranchesQuery
  withBranches: branchExistsInBuildTypeQuery
}

export default function BuildTypePageContainer({
  queries,
  entryPoints,
}: EntryPointProps<Queries, NestedEntryPoints, {}, {}>) {
  const {buildTypeId: buildTypeIdString} = useParams()
  const buildTypeId = buildTypeIdString != null ? toBuildTypeId(buildTypeIdString) : undefined
  useRefetchBuildTypeOnPermissionsChange(buildTypeId)

  return (
    <BuildTypePage
      key={buildTypeId}
      buildTypeId={buildTypeId!}
      buildTypeHistoryQuery={
        queries.buildTypeHistory as PreloadedQuery<BuildTypeHistoryQuery> | undefined
      }
      permalinksQuery={queries.permalinks as PreloadedQuery<PermalinksQuery> | undefined}
      branchesQueryRef={queries.branches}
      withBranchesQueryRef={queries.withBranches}
      entryPoints={entryPoints}
    />
  )
}

export type BuildTypePageContainerComponent = typeof BuildTypePageContainer
