import {
  ControlsHeight,
  ControlsHeightContext,
} from '@jetbrains/ring-ui-built/components/global/controls-height'
import classNames from 'classnames'
import {memo} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import useDocumentTitle from '../../../../hooks/useDocumentTitle'
import useStatusSubscription from '../../../../hooks/useStatusSubscription'
import {Policy} from '../../../../rest/branches'
import {getBuildType} from '../../../../selectors'
import type {BuildTypeId, ProjectId} from '../../../../types'
import BranchFilterBadge from '../../../common/Badges/BranchFilterBadge/BranchFilterBadge'
import BuildTypeInvestigationsBadge from '../../../common/Badges/BuildTypeInvestigationsBadge/BuildTypeInvestigationsBadge'
import HealthBadge from '../../../common/Badges/HealthBadge/HealthBadge'
import ResponsiveBadgeContainer from '../../../common/Badges/ResponsiveBadgeContainer/ResponsiveBadgeContainer'
import type {BranchSelectBranchesQuery} from '../../../common/BranchSelect/__generated__/BranchSelectBranchesQuery.graphql'
import BuildTypeActionsDropdown from '../../../common/BuildTypeActionsDropdown/BuildTypeActionsDropdown'
import Description from '../../../common/Description/Description.container'
import EditEntity from '../../../common/EditEntity/EditEntity.container'
import FavoriteStar from '../../../common/FavoriteStar/FavoriteStar.container'
import NoWrap from '../../../common/NoWrap/NoWrap'
import PageTitle from '../../../common/PageTitle/PageTitle'
import OverviewHeaderIcon from '../../../common/ProjectOrBuildTypeIcon/OverviewHeaderIcon.container'
import RunBuildInSelectedBranch from '../../../common/RunBuild/RunBuildInSelectedBranch.container'
import SequenceLoader from '../../../common/SequenceLoader/SequenceLoader'
import {BuildTypeSystemProblemsBadge} from '../../PipelinesPages/components/Badges'

import PausedBadge from './PausedBadge/PausedBadge'

import styles from './BuildTypePageHeader.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const icon = <OverviewHeaderIcon size="L" />

type Props = {
  className?: string
  buildTypeId: BuildTypeId
  projectId: ProjectId | null | undefined
  branchesQueryRef: PreloadedQuery<BranchSelectBranchesQuery>
}
function BuildTypePageHeader({className, buildTypeId, projectId, branchesQueryRef}: Props) {
  const {name, paused} = useAppSelector(state => getBuildType(state, buildTypeId)) ?? {}
  const headingClassNames = classNames(styles.heading, className)

  useStatusSubscription({buildTypeId, projectId})
  useDocumentTitle(name != null ? `${name} — TeamCity` : null)

  return (
    <div
      data-test="overview-header"
      data-project-id={projectId}
      data-buildtype-id={buildTypeId}
      className={styles.header}
    >
      <div className={styles.top}>
        <PageTitle className={headingClassNames}>
          {icon}
          <span>{name}</span>
          <NoWrap>
            <FavoriteStar className={styles.star} buildTypeId={buildTypeId} />
          </NoWrap>
        </PageTitle>
        <ControlsHeightContext.Provider value={ControlsHeight.M}>
          <SequenceLoader
            showFirstLoadingItem
            className={styles.topSequenceLoader}
            loader=""
            reverse
          >
            <RunBuildInSelectedBranch
              seqKey="RunBuildInSelectedBranch"
              buildTypeId={buildTypeId}
              withVisibilityDetect={false}
              isPrimary
            />
            <BuildTypeActionsDropdown
              seqKey="Actions"
              withHint
              hintEntityName="build configuration"
            />
            <EditEntity seqKey="EditEntity" />
          </SequenceLoader>
        </ControlsHeightContext.Provider>
      </div>
      <Description className={styles.description} lines={3} buildTypeId={buildTypeId} />
      <ResponsiveBadgeContainer className={styles.subHeader}>
        {Boolean(paused) && <PausedBadge seqKey="pausedBadge" buildTypeId={buildTypeId} />}
        <BranchFilterBadge
          seqKey="branchBadge"
          branchesQueryRef={branchesQueryRef}
          policy={Policy.ALL_BRANCHES}
        />
        <BuildTypeSystemProblemsBadge
          seqKey="systemProblemsBadge"
          buildTypeId={buildTypeId}
          className={styles.systemProblems}
        />
        <BuildTypeInvestigationsBadge seqKey="investigations" buildTypeId={buildTypeId} />
        <HealthBadge seqKey="healthBadge" />
      </ResponsiveBadgeContainer>
    </div>
  )
}
export default memo(BuildTypePageHeader)
