import Link from '@jetbrains/ring-ui-built/components/link/link'
import classNames from 'classnames'
import {useCallback} from 'react'

import {useAppSelector} from '../../../../hooks/react-redux'
import {usePermission} from '../../../../hooks/usePermission'
import {getBuildTypeArg} from '../../../../rest/buildTypes'
import {getIsReadOnly} from '../../../../selectors'
import {restApi} from '../../../../services/rest'
import type {BuildTypeId, ProjectId} from '../../../../types'
import {Permission} from '../../../../types'
import {BS} from '../../../../types/BS_types'
import {resolveWebEntityLink, WebEntityType} from '../../../../utils/entityLinks'
import {getActionsPath} from '../../ActionsDropdown/ActionsDropdown.utils'

import styles from './ActivateButton.module.css'

type Props = {
  projectId?: ProjectId
  buildTypeId: BuildTypeId
  text: string | undefined
  newLineBeforeButton: boolean
}

function ActivateButton({projectId, buildTypeId, text, newLineBeforeButton}: Props) {
  const isReadonly = useAppSelector(state => getIsReadOnly(state, projectId))
  const canActivateBuild = usePermission(Permission.PAUSE_ACTIVATE_BUILD_CONFIGURATION, projectId)
  const entityHref = resolveWebEntityLink(WebEntityType.BUILD_TYPE, buildTypeId)
  const path = getActionsPath(entityHref)

  const [fetchSingleBuildTypeData] =
    restApi.endpoints.getBuildTypeNormalized.useLazyQuerySubscription()
  const [fetchHtml] = restApi.endpoints.getHtml.useLazyQuerySubscription()

  const reload = useCallback(() => {
    fetchSingleBuildTypeData(getBuildTypeArg(buildTypeId))
    if (path != null) {
      fetchHtml({path})
    }
  }, [buildTypeId, fetchHtml, fetchSingleBuildTypeData, path])

  const handleActivateClick = useCallback(() => {
    BS?.PauseBuildTypeDialog?.showPauseBuildTypeDialog(buildTypeId, false, false, text, true).then(
      reload,
    )
  }, [buildTypeId, reload, text])

  return (
    canActivateBuild &&
    !isReadonly && (
      <Link
        className={classNames(styles.activate, {[styles.lineBreak]: newLineBeforeButton})}
        onClick={handleActivateClick}
      >
        {'Activate...'}
      </Link>
    )
  )
}
export default ActivateButton
