import {withHandlers} from 'recompose'

import compose from 'lodash/flowRight'
import {Suspense} from 'react'
import type {ConnectedProps} from 'react-redux'
import {connect} from 'react-redux'

import {toggleOverview} from '../../../actions/overview'
import type {State} from '../../../reducers/types'
import {getIsBuildTypeOnOverview, getIsProjectOnOverview} from '../../../selectors'
import {getProjectBuildTypeFilter} from '../../../types'

import FavoriteStar from './FavoriteStar'
import type {OwnProps, Props, StateProps} from './FavoriteStar.types'

const mapStateToProps = (state: State, {projectId, buildTypeId}: OwnProps): StateProps => ({
  isStarred: buildTypeId
    ? getIsBuildTypeOnOverview(state, buildTypeId)
    : getIsProjectOnOverview(state, projectId),
})

const actionCreators = {
  onStar: toggleOverview,
}

const connector = connect(mapStateToProps, actionCreators)

export default compose(
  connector,
  withHandlers({
    onStar: (props: OwnProps & ConnectedProps<typeof connector>) => () => {
      const node = getProjectBuildTypeFilter(props)
      if (node != null) {
        props.onStar(node, !props.isStarred)
      }
    },
  }),
)(function FavoriteStarContainer(props: Props) {
  return (
    <Suspense>
      <FavoriteStar {...props} />
    </Suspense>
  )
})
