import {memo, useCallback, useState} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import BranchFilter from '../../../../containers/BranchFilter'
import type {Policy} from '../../../../rest/branches'
import type {BranchSelectBranchesQuery} from '../../BranchSelect/__generated__/BranchSelectBranchesQuery.graphql'
import {useSequenceLoaderReadyHandler} from '../../SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../SequenceLoader/SequenceLoader.types'

import styles from './BranchFilterBadge.module.css'

type Props = {
  headId?: string | null
  branchesQueryRef?: PreloadedQuery<BranchSelectBranchesQuery>
  policy: Policy
} & SeqProps

function BranchFilterBadge({headId, branchesQueryRef, policy}: Props) {
  const [hasBranch, setHasBranch] = useState(branchesQueryRef != null)

  const branchSelectLoadHandler = useCallback(({shouldBeVisible}: {shouldBeVisible: boolean}) => {
    setHasBranch(shouldBeVisible)
  }, [])

  useSequenceLoaderReadyHandler(true)
  if (!hasBranch || branchesQueryRef == null) {
    return null
  }

  return (
    <BranchFilter
      key="BranchFilter"
      seqKey="BranchFilter"
      badgeClassName={styles.badge}
      headId={headId}
      branchesQueryRef={branchesQueryRef}
      policy={policy}
      onLoad={branchSelectLoadHandler}
      isBadge
      inline
      withTooltip
    />
  )
}

export default memo(BranchFilterBadge)
