import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {Suspense, useMemo} from 'react'

import {useAppSelector} from '../../../../../hooks/react-redux'
import {useIsAutodetectTimeZone} from '../../../../../hooks/useIsAutodetectTimeZone'
import {getBuildTypeArg} from '../../../../../rest/buildTypes'
import {getBuildType} from '../../../../../selectors'
import {restApi} from '../../../../../services/rest'
import type {BuildTypeId} from '../../../../../types'
import Avatar, {Size} from '../../../../common/Avatar/Avatar.container'
import Badge from '../../../../common/Badge/Badge'
import ActivateButton from '../../../../common/BuildTypePauseInfo/ActivateButton/ActivateButton'
import Icon from '../../../../common/Icon/Icon'
import {useSequenceLoaderReadyHandler} from '../../../../common/SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../../common/SequenceLoader/SequenceLoader.types'

import {getDetails} from './PausedBadge.utils'

import styles from './PausedBadge.module.css'

type Props = {
  buildTypeId: BuildTypeId
} & SeqProps
function PausedBadge({buildTypeId}: Props) {
  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const {pauseComment, isReady} = restApi.endpoints.getBuildTypeNormalized.useQuery(
    getBuildTypeArg(buildTypeId),
    {
      selectFromResult: ({data}) => {
        const {result, entities} = data ?? {}
        return {
          pauseComment: entities?.buildTypes?.[result!]?.pauseComment,
          isReady: data != null,
        }
      },
    },
  )
  useSequenceLoaderReadyHandler(isReady)
  const projectId = useAppSelector(state => getBuildType(state, buildTypeId)?.projectId)
  const {user, details, comment} = useMemo(
    () => getDetails(pauseComment, isAutodetectTimeZone),
    [isAutodetectTimeZone, pauseComment],
  )

  return (
    <Badge className={styles.wrapper}>
      <div className={styles.label}>{'Paused'}</div>
      <div className={styles.detailsWrapper}>
        {!pauseComment || (!user && !details && !comment) ? (
          <div>{'Build configuration was paused'}</div>
        ) : (
          <>
            {user && <Avatar user={user} size={Size.Size20} />}
            <Tooltip className={styles.details} title={details} delay={500} selfOverflowOnly>
              <span>{details}</span>
            </Tooltip>
            {comment && (
              <Tooltip title={comment} delay={500}>
                <Icon name="comment" />
              </Tooltip>
            )}
          </>
        )}
      </div>
      <div className={styles.activateButton}>
        <Suspense>
          <ActivateButton
            projectId={projectId}
            buildTypeId={buildTypeId}
            text={pauseComment?.text}
            newLineBeforeButton={false}
          />
        </Suspense>
      </div>
    </Badge>
  )
}
export default PausedBadge
